 return `<details class="history-year-group" data-history-year-group="${esc(year)}"${open}><summary class="history-year-heading"><span class="history-year-title"><span class="history-year-chevron" aria-hidden="true"></span><b>${esc(year)}</b></span><span class="history-year-status">${esc(status)}</span></summary><div class="history-year-body"><div class="history-year-actions"><button class="btn secondary" type="button" data-history-year-action="select" data-history-year="${esc(year)}">Select All Months</button><button class="btn secondary" type="button" data-history-year-action="clear" data-history-year="${esc(year)}">Clear Months</button></div><div class="history-month-grid">${months}</div></div></details>`
