function remoteCustomerPayload(c){return {id:c.id,company_id:c.companyId||currentAccess().company_id,company_name:c.company,classification:c.classification||'Other',pricing_category_id:c.pricingCategoryId||null,default_quotation_template_id:c.defaultQuotationTemplateId||null,assigned_user_email:c.assignedUserEmail||currentEmail(),created_by_email:c.createdByEmail||currentEmail(),distance_km:Number(c.distanceKm||0),company_phone:c.companyPhone||'',address:c.address||'',payment_terms:c.terms||'',tin_number:c.tinNumber||'',business_registration_no:c.brnNumber||'',sst_number:c.sstNumber||'',msic_code:c.msicCode||'',business_activity:c.businessActivity||'',notes:c.notes||'',contacts:c.contacts||[],status:c.status||'active',updated_at:new Date().toISOString()}}
async function loadSecureCustomers(){
 const client=customerClient();if(!client){customerSyncMode='local';customerSyncError='Secure customer connection is unavailable.';renderCustomerAccessNotice();return customers()}
 try{
   const {data,error}=await client.from('ks_customers').select('*').eq('status','active').order('company_name');
   if(error)throw error;
   let rows=(data||[]).map(normalizeCustomerRecord);
   const local=store.get('ks_customers',[]);
   if(!rows.length&&local.length){
     const imported=local.map(c=>remoteCustomerPayload({...c,id:customerUuid(c.id),companyId:currentAccess().company_id,classification:c.classification||'Other',assignedUserEmail:currentEmail(),createdByEmail:currentEmail()}));
     const result=await client.from('ks_customers').upsert(imported,{onConflict:'id'}).select('*');
     if(!result.error)rows=(result.data||[]).map(normalizeCustomerRecord);
   }
   rows=await importCompanyMasters(client,rows);
   secureCustomers=rows;customerSyncMode='supabase';customerSyncError='';store.set('ks_customers_backup_v105',rows);renderCustomerAccessNotice();window.dispatchEvent(new CustomEvent('keysuite-customers-changed',{detail:{customers:rows.slice()}}));refreshAll();return rows;
 }catch(error){
   console.warn('Secure customers unavailable',error);customerSyncMode='local';customerSyncError=String(error?.message||error);renderCustomerAccessNotice();return customers();
 }
}
