 const id=customerId===undefined?($('qCustomer')?.value||quotationPricingCustomerId||''):String(customerId||'');
 hidden.value=id;
 const customer=customers().find(x=>x.id===id),status=$('startCustomerStatus'),search=$('startCustomerSearch');
 if(search)search.value=customer?.company||'';
