 const contact=contacts[Number($('qContact').value)]||{};
 if($('qPrintedContact')&&!$('qPrintedContact').value)$('qPrintedContact').value=[contact.prefix,contact.name].filter(Boolean).join(' ');
 updateQuotationContactInfo();
