let twoLineTarget=null;
function openTwoLineEditor(target,title){
  twoLineTarget=target;
  $('twoLineTitle').textContent=title;
  $('twoLine1').value=$(target).value||'';
  $('twoLine2').value=$(target+'2').value||'';
  $('twoLineDialog').showModal();
}
